const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nycPoint = ee.Geometry.Point([-74.0060, 40.7128]);
  const date1 = '2019-01-29';
  const date2 = '2019-02-05';
  const collectionName = 'ECMWF/ERA5/DAILY';
  const tempBand = 'mean_2m_air_temperature';

  // 2. Data Acquisition & Check
  const image1_col = ee.ImageCollection(collectionName)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .select(tempBand);

  const image2_col = ee.ImageCollection(collectionName)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .select(tempBand);

  const image1_count = image1_col.size().getInfo();
  const image2_count = image2_col.size().getInfo();

  if (image1_count === 0 || image2_count === 0) {
    console.log(`Image count on ${date1}: ${image1_count}`);
    console.log(`Image count on ${date2}: ${image2_count}`);
    console.log('Empty Collection: No daily image found for one or both dates.');
    console.log('C1');
    return;
  }

  const image1 = image1_col.first();
  const image2 = image2_col.first();

  // 3. Processing & Calculation
  const tempK1_info = image1.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: nycPoint,
    scale: 1000,
  }).get(tempBand);

  const tempK2_info = image2.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: nycPoint,
    scale: 1000,
  }).get(tempBand);

  // Use a Promise to wait for both values
  const [tempK1, tempK2] = await Promise.all([
    ee.Number(tempK1_info).getInfo(),
    ee.Number(tempK2_info).getInfo()
  ]);

  // 4. Validation & Final Answer
  if (tempK1 === null || tempK2 === null) {
    console.log(`Temp ${date1} (K): ${tempK1}`);
    console.log(`Temp ${date2} (K): ${tempK2}`);
    console.log('Calculation Failure: Could not extract temperature value.');
    console.log('C3');
    return;
  }

  // C2 check is not strictly necessary for ERA5 but good practice.
  // A null from reduceRegion for a point on a global dataset is a C3 failure.

  const tempC1 = tempK1 - 273.15;
  const tempC2 = tempK2 - 273.15;

  const tempDiff = Math.abs(tempC1 - tempC2);

  console.log(`Temperature on ${date1}: ${tempC1.toFixed(2)} C`);
  console.log(`Temperature on ${date2}: ${tempC2.toFixed(2)} C`);
  console.log(`Absolute difference: ${tempDiff.toFixed(2)} C`);

  if (tempDiff >= 24) {
    console.log('B');
  } else {
    console.log('A');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log('D');
});
